const svg=$('#bn-svg'), out=$('#bn-out'), pr=$('#bn-pr'), prL=$('#bn-pr-lbl');
const bRain=$('#bn-rain'), bSpr=$('#bn-spr'), bWet=$('#bn-wet'), bClear=$('#bn-clear');
const W=640,H=300;
// fixed CPTs (R=rain, S=sprinkler, both causes of W=wet grass)
const pS=0.4;                     // P(Sprinkler)
function pWgivenRS(r,s){           // P(WetGrass=1 | R=r, S=s)
  if(r&&s) return 0.99; if(r&&!s) return 0.9; if(!r&&s) return 0.9; return 0.05;
}
// evidence: each of R,S,W is null (unobserved) or 0/1
let ev={R:null,S:null,W:null};
// enumerate full joint over (R,S,W) consistent with evidence; return posteriors + Z
function infer(){
  const pR=+pr.value;
  let Z=0; const post={R:[0,0],S:[0,0],W:[0,0]};
  for(let r=0;r<2;r++) for(let s=0;s<2;s++) for(let w=0;w<2;w++){
    if(ev.R!==null&&ev.R!==r) continue;
    if(ev.S!==null&&ev.S!==s) continue;
    if(ev.W!==null&&ev.W!==w) continue;
    const pw=pWgivenRS(r,s); const pjoint=(r?pR:1-pR)*(s?pS:1-pS)*(w?pw:1-pw);
    Z+=pjoint; post.R[r]+=pjoint; post.S[s]+=pjoint; post.W[w]+=pjoint;
  }
  for(const k of ['R','S','W']){ post[k][0]/=Z; post[k][1]/=Z; }
  return {post,Z};
}
// d-separation of R and S given current evidence set Z (here the only path is the collider R->W<-S)
function rsDependentGivenW(){ return ev.W!==null; } // observing collider W (a descendant set is empty here) opens the path
function nodeColor(name){ const v=ev[name]; if(v===null) return 'var(--panel2)'; return v? 'var(--green)' : 'var(--pink)'; }
function render(){
  svg.innerHTML='';
  prL.textContent='P(Rain) = '+(+pr.value).toFixed(2);
  bRain.classList.toggle('active', ev.R!==null);
  bSpr.classList.toggle('active', ev.S!==null);
  bWet.classList.toggle('active', ev.W!==null);
  // node positions: Rain (top-left), Sprinkler (top-right), WetGrass (bottom-center)
  const R=[180,80], S=[460,80], Wn=[320,210];
  drawArrow(svg, R, Wn, {color:'var(--blue)', markerId:'arr-bn', width:1.8});
  drawArrow(svg, S, Wn, {color:'var(--blue)', markerId:'arr-bn', width:1.8});
  drawNode(svg, R[0],R[1],'R',{r:26,fill:nodeColor('R'),stroke:'var(--cyan)'});
  drawNode(svg, S[0],S[1],'S',{r:26,fill:nodeColor('S'),stroke:'var(--cyan)'});
  drawNode(svg, Wn[0],Wn[1],'W',{r:26,fill:nodeColor('W'),stroke:'var(--yellow)'});
  function cap(x,y,t,c){ const e=SVG('text',{x,y,'text-anchor':'middle','font-size':12,fill:c||'var(--mute)'}); e.textContent=t; svg.appendChild(e); }
  cap(R[0],R[1]-34,'Rain'); cap(S[0],S[1]-34,'Sprinkler'); cap(Wn[0],Wn[1]+44,'WetGrass');
  const {post,Z}=infer();
  const dep=rsDependentGivenW();
  function ed(name){ const v=ev[name]; return v===null?'—':(v?'true':'false'); }
  out.textContent =
    'factorization:  p(R,S,W) = P(R)·P(S)·P(W | R,S)\n'+
    'evidence:  R='+ed('R')+',  S='+ed('S')+',  W='+ed('W')+'   (green=true, pink=false, grey=unobserved)\n'+
    'posteriors:  P(Rain=1 | evidence) = '+post.R[1].toFixed(3)+',   P(Sprinkler=1 | evidence) = '+post.S[1].toFixed(3)+',   P(WetGrass=1 | evidence) = '+post.W[1].toFixed(3)+'\n'+
    'd-separation query  Rain ⟂ Sprinkler ?  the only path is the collider R→W←S:\n'+
    (dep ? '  WetGrass observed ⇒ collider OPEN ⇒ Rain and Sprinkler are DEPENDENT (explaining away)'
         : '  WetGrass unobserved ⇒ collider BLOCKED ⇒ Rain ⟂ Sprinkler (independent)');
}
function toggle(name){ ev[name] = (ev[name]===null) ? 1 : (ev[name]===1 ? 0 : null); render(); }
bRain.addEventListener('click',()=>toggle('R'));
bSpr.addEventListener('click',()=>toggle('S'));
bWet.addEventListener('click',()=>toggle('W'));
bClear.addEventListener('click',()=>{ ev={R:null,S:null,W:null}; render(); });
pr.addEventListener('input',render);
render();

const svg=$('#mrf-svg'), out=$('#mrf-out'), Tsl=$('#mrf-T'), TL=$('#mrf-T-lbl'), relax=$('#mrf-relax'), reset=$('#mrf-reset');
const W=640,H=320, N=6, J=1;
// deterministic PRNG so the page is reproducible
let seed=12345; function rnd(){ seed=(seed*1664525+1013904223)>>>0; return seed/4294967296; }
let spin=[];
function initGrid(){ seed=12345; spin=[]; for(let i=0;i<N;i++){ spin.push([]); for(let j=0;j<N;j++) spin[i].push(rnd()<0.5?-1:1); } }
function neigh(i,j){ const ns=[]; if(i>0)ns.push([i-1,j]); if(i<N-1)ns.push([i+1,j]); if(j>0)ns.push([i,j-1]); if(j<N-1)ns.push([i,j+1]); return ns; }
function energy(){ let E=0; for(let i=0;i<N;i++) for(let j=0;j<N;j++){ if(i<N-1) E-=J*spin[i][j]*spin[i+1][j]; if(j<N-1) E-=J*spin[i][j]*spin[i][j+1]; } return E; }
function magnet(){ let m=0; for(let i=0;i<N;i++) for(let j=0;j<N;j++) m+=spin[i][j]; return m/(N*N); }
function sweep(){ const T=+Tsl.value; for(let i=0;i<N;i++) for(let j=0;j<N;j++){ let s=0; for(const [a,b] of neigh(i,j)) s+=spin[a][b]; const pPlus=1/(1+Math.exp(-2*J*s/T)); spin[i][j]= rnd()<pPlus?1:-1; } }
const cx=2, cy=2; // highlighted spin for the conditional readout
function render(){
  svg.innerHTML='';
  TL.textContent='T = '+(+Tsl.value).toFixed(1);
  const gx=40, gy=30, cell=42;
  for(let i=0;i<N;i++) for(let j=0;j<N;j++){
    const up=spin[i][j]===1;
    svg.appendChild(SVG('rect',{x:gx+j*cell,y:gy+i*cell,width:cell-3,height:cell-3,rx:5,fill:up?'var(--cyan)':'var(--violet)',opacity:0.85}));
  }
  // highlight the (cx,cy) spin and its blanket
  svg.appendChild(SVG('rect',{x:gx+cy*cell-2,y:gy+cx*cell-2,width:cell+1,height:cell+1,rx:6,fill:'none',stroke:'var(--yellow)','stroke-width':3}));
  for(const [a,b] of neigh(cx,cy)) svg.appendChild(SVG('rect',{x:gx+b*cell-1,y:gy+a*cell-1,width:cell-1,height:cell-1,rx:5,fill:'none',stroke:'var(--green)','stroke-width':2,'stroke-dasharray':'4 3'}));
  function leg(x,y,c,t){ svg.appendChild(SVG('rect',{x,y:y-9,width:14,height:14,rx:3,fill:c})); const tt=SVG('text',{x:x+20,y:y+3,'font-size':12,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(330,60,'var(--cyan)','spin = +1'); leg(330,86,'var(--violet)','spin = −1');
  const t1=SVG('text',{x:330,y:120,'font-size':12,fill:'var(--yellow)'}); t1.textContent='yellow box: the highlighted spin'; svg.appendChild(t1);
  const t2=SVG('text',{x:330,y:140,'font-size':12,fill:'var(--green)'}); t2.textContent='green dashes: its Markov blanket'; svg.appendChild(t2);
  const t3=SVG('text',{x:330,y:160,'font-size':12,fill:'var(--mute)'}); t3.textContent='(= its neighbors, all the conditional needs)'; svg.appendChild(t3);
  // local conditional for the highlighted spin
  const T=+Tsl.value; let s=0; for(const [a,b] of neigh(cx,cy)) s+=spin[a][b];
  const pPlus=1/(1+Math.exp(-2*J*s/T));
  out.textContent =
    'p(x) = (1/Z) exp(−E),   E = −J Σ x_i x_j   over edges,   J = 1\n'+
    'energy E = '+energy().toFixed(1)+',    magnetization = '+magnet().toFixed(3)+'\n'+
    'highlighted spin: neighbor sum Σ x_j = '+s+'\n'+
    'full conditional  p(x = +1 | blanket) = σ(2J·Σ x_j / T) = '+pPlus.toFixed(3)+'   — uses only the 4 neighbors; Z cancels';
}
Tsl.addEventListener('input',render);
relax.addEventListener('click',()=>{ for(let k=0;k<200;k++) sweep(); render(); });
reset.addEventListener('click',()=>{ initGrid(); render(); });
initGrid(); render();

const svg=$('#ve-svg'), out=$('#ve-out'), cpl=$('#ve-coupling'), cplL=$('#ve-coupling-lbl'), step=$('#ve-step'), reset=$('#ve-reset');
const W=640,H=280, N=4; // chain X1-X2-X3-X4, binary, query = X4
// edge potential ψ(a,b) = exp(coupling) if a==b else 1
function psi(a,b){ return a===b ? Math.exp(+cpl.value) : 1; }
// node singleton biases (deterministic, mild) to make the marginal non-uniform
const bias=[[1,1.4],[1,1],[1.3,1],[1,1.1]]; // [P~(0),P~(1)] up to scale, per node
// factors: start with singletons f_i(x_i) and pairwise g_{i,i+1}(x_i,x_{i+1})
// elimination order eliminates X1, then X2, then X3, leaving marginal over X4.
let elimStep=0; // 0..3 (3 = done, marginal ready)
// compute the chain marginal of X4 by eliminating X1,X2,X3 in order; capture intermediate τ
function run(){
  // tau over current frontier variable; start as singleton on X1
  let tau=[bias[0][0], bias[0][1]]; // factor over X1
  const log=[];
  log.push('start: τ(X1) = singleton bias = ['+tau.map(t=>t.toFixed(2)).join(', ')+']');
  // eliminate X1: τ2(x2) = Σ_{x1} τ(x1) ψ(x1,x2) · bias(X2)
  function elimInto(prevTau, nextNode){
    const res=[0,0];
    for(let xn=0;xn<2;xn++){ let s=0; for(let xp=0;xp<2;xp++) s+=prevTau[xp]*psi(xp,xn); res[xn]=s*bias[nextNode][xn]; }
    return res;
  }
  let cur=tau; const taus=[tau];
  for(let k=1;k<N;k++){ cur=elimInto(cur,k); taus.push(cur);
    log.push('eliminate X'+k+':  τ(X'+(k+1)+') = Σ_{x'+k+'} τ(X'+k+')·ψ(x'+k+',x'+(k+1)+')·b(X'+(k+1)+') = ['+cur.map(t=>t.toFixed(3)).join(', ')+']');
  }
  const Z=cur[0]+cur[1]; const marg=[cur[0]/Z,cur[1]/Z];
  return {taus,log,marg};
}
function render(){
  svg.innerHTML='';
  cplL.textContent='coupling = '+(+cpl.value).toFixed(1);
  const {taus,log,marg}=run();
  // draw chain
  const xs=[110,250,390,530], y=90;
  for(let i=0;i<N-1;i++){
    const eliminated = i < elimStep; // edge consumed if its left endpoint already eliminated
    svg.appendChild(SVG('line',{x1:xs[i],y1:y,x2:xs[i+1],y2:y,stroke:eliminated?'var(--line)':'var(--blue)','stroke-width':eliminated?1:2.4,'stroke-dasharray':eliminated?'4 4':null}));
  }
  for(let i=0;i<N;i++){
    const gone = i < elimStep;
    const isQuery = i===N-1;
    drawNode(svg, xs[i], y, 'X'+(i+1), {r:24, fill: gone?'var(--panel)':(isQuery?'var(--yellow)':'var(--panel2)'), stroke: gone?'var(--line)':(isQuery?'var(--yellow)':'var(--cyan)'), textColor: gone?'var(--mute)':'#fff'});
    if(gone){ const x=SVG('text',{x:xs[i],y:y-32,'text-anchor':'middle','font-size':16,fill:'var(--pink)'}); x.textContent='Σ'; svg.appendChild(x); }
  }
  const lbl=SVG('text',{x:xs[N-1],y:y+44,'text-anchor':'middle','font-size':12,fill:'var(--yellow)'}); lbl.textContent='query'; svg.appendChild(lbl);
  // status text in svg
  const st=SVG('text',{x:W/2,y:160,'text-anchor':'middle','font-size':13,fill:'var(--mute)'});
  st.textContent = elimStep===0 ? 'press “eliminate next variable” to push the sum inward' : (elimStep>=N-1 ? 'all of X1,X2,X3 eliminated — marginal over X4 ready' : 'eliminated X1.. so far');
  svg.appendChild(st);
  const shown = log.slice(0, elimStep+1).join('\n');
  out.textContent =
    'chain X1—X2—X3—X4 (binary), edge ψ(a,b)=exp(coupling)·[a=b]+[a≠b], query = X4\n'+
    shown+'\n'+
    (elimStep>=N-1 ? ('\nmarginal  p(X4) = ['+marg.map(m=>m.toFixed(3)).join(', ')+']  (normalized)\ninduced width of this left-to-right order = 1  ⇒  linear-time (treewidth 1)' )
                   : '\n(induced width so far = 1: each τ is over a single variable)');
}
cpl.addEventListener('input',render);
step.addEventListener('click',()=>{ if(elimStep<N-1){ elimStep++; render(); } });
reset.addEventListener('click',()=>{ elimStep=0; render(); });
render();

const svg=$('#bp-svg'), out=$('#bp-out'), ag=$('#bp-agree'), agL=$('#bp-agree-lbl'), step=$('#bp-step'), reset=$('#bp-reset');
const W=640,H=300; // chain factor graph: X1 - f12 - X2 - f23 - X3, binary
function f(a,b){ return a===b ? Math.exp(+ag.value) : 1; }     // pairwise factor
const node=[[0.6,1.4],[1,1],[1.3,0.7]];                         // X1,X2,X3 singleton factors
function norm(v){ const s=v[0]+v[1]; return [v[0]/s, v[1]/s]; }
// messages we will fill, in sweep order (leaves -> center -> leaves)
// step 0: none; 1: μ f12->X2 ; 2: μ f23->X2 ; 3: marginal X2 ; 4: μ f12->X1 & f23->X3 + marginals X1,X3 (done)
let s=0;
function compute(){
  // incoming variable->factor from leaves are just the leaf singletons
  const mX1f=[node[0][0],node[0][1]];
  const mX3f=[node[2][0],node[2][1]];
  // μ f12 -> X2 (x2) = Σ_x1 f(x1,x2)·mX1f(x1)
  const mf12_X2=[0,0]; for(let x2=0;x2<2;x2++){ let t=0; for(let x1=0;x1<2;x1++) t+=f(x1,x2)*mX1f[x1]; mf12_X2[x2]=t; }
  const mf23_X2=[0,0]; for(let x2=0;x2<2;x2++){ let t=0; for(let x3=0;x3<2;x3++) t+=f(x2,x3)*mX3f[x3]; mf23_X2[x2]=t; }
  // marginal X2 ∝ node(X2)·mf12_X2·mf23_X2
  const margX2=norm([node[1][0]*mf12_X2[0]*mf23_X2[0], node[1][1]*mf12_X2[1]*mf23_X2[1]]);
  // back-sweep: μ X2->f12 = node(X2)·mf23_X2 ; μ f12->X1(x1)=Σ_x2 f(x1,x2)·μ X2->f12(x2)
  const mX2_f12=[node[1][0]*mf23_X2[0], node[1][1]*mf23_X2[1]];
  const mf12_X1=[0,0]; for(let x1=0;x1<2;x1++){ let t=0; for(let x2=0;x2<2;x2++) t+=f(x1,x2)*mX2_f12[x2]; mf12_X1[x1]=t; }
  const mX2_f23=[node[1][0]*mf12_X2[0], node[1][1]*mf12_X2[1]];
  const mf23_X3=[0,0]; for(let x3=0;x3<2;x3++){ let t=0; for(let x2=0;x2<2;x2++) t+=f(x2,x3)*mX2_f23[x2]; mf23_X3[x3]=t; }
  const margX1=norm([node[0][0]*mf12_X1[0], node[0][1]*mf12_X1[1]]);
  const margX3=norm([node[2][0]*mf23_X3[0], node[2][1]*mf23_X3[1]]);
  return {mf12_X2:norm(mf12_X2),mf23_X2:norm(mf23_X2),margX1,margX2,margX3};
}
function render(){
  svg.innerHTML='';
  agL.textContent='agreement = '+(+ag.value).toFixed(1);
  const r=compute();
  const y=90; const X1=[90,y],F12=[210,y],X2=[330,y],F23=[450,y],X3=[570,y];
  // edges
  [[X1,F12],[F12,X2],[X2,F23],[F23,X3]].forEach(([a,b])=>svg.appendChild(SVG('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:'var(--line)','stroke-width':2})));
  // factors as squares
  function fac(p){ svg.appendChild(SVG('rect',{x:p[0]-12,y:p[1]-12,width:24,height:24,fill:'var(--panel2)',stroke:'var(--pink)','stroke-width':1.8})); }
  fac(F12); fac(F23);
  drawNode(svg,X1[0],X1[1],'X₁',{r:22,stroke:'var(--cyan)'});
  drawNode(svg,X2[0],X2[1],'X₂',{r:22,stroke:'var(--cyan)'});
  drawNode(svg,X3[0],X3[1],'X₃',{r:22,stroke:'var(--cyan)'});
  function flbl(p,t){ const e=SVG('text',{x:p[0],y:p[1]+30,'text-anchor':'middle','font-size':11,fill:'var(--pink)'}); e.textContent=t; svg.appendChild(e); }
  flbl(F12,'f₁₂'); flbl(F23,'f₂₃');
  // animate message arrows up to step s
  function msg(a,b,color){ drawArrow(svg,a,b,{color,markerId:'arr-bp-'+color.replace(/[^a-z]/g,''),width:2,curve:-22}); }
  if(s>=1) msg(F12,X2,'var(--yellow)');
  if(s>=2) msg(F23,X2,'var(--yellow)');
  if(s>=4){ msg(F12,X1,'var(--green)'); msg(F23,X3,'var(--green)'); }
  const steps=[
    'press “advance one message” to flow the sum–product messages',
    'forward: μ(f₁₂→X₂) = Σ_{x₁} f₁₂(x₁,x₂)·μ(X₁→f₁₂)(x₁) = ['+r.mf12_X2.map(v=>v.toFixed(3)).join(', ')+']',
    'forward: μ(f₂₃→X₂) = Σ_{x₃} f₂₃(x₂,x₃)·μ(X₃→f₂₃)(x₃) = ['+r.mf23_X2.map(v=>v.toFixed(3)).join(', ')+']',
    'marginal at X₂ ∝ b(X₂)·μ(f₁₂→X₂)·μ(f₂₃→X₂)  ⇒  p(X₂) = ['+r.margX2.map(v=>v.toFixed(3)).join(', ')+']',
    'back-sweep done: p(X₁) = ['+r.margX1.map(v=>v.toFixed(3)).join(', ')+'],  p(X₃) = ['+r.margX3.map(v=>v.toFixed(3)).join(', ')+']  — all marginals exact in two sweeps'
  ];
  out.textContent =
    'factor graph  X₁ — f₁₂ — X₂ — f₂₃ — X₃  (binary), f(a,b)=exp(agreement)·[a=b]+[a≠b]\n'+
    steps.slice(0, s+1).join('\n');
}
ag.addEventListener('input',render);
step.addEventListener('click',()=>{ if(s<4){ s++; render(); } });
reset.addEventListener('click',()=>{ s=0; render(); });
render();

const svg=$('#vi-svg'), out=$('#vi-out'), corr=$('#vi-corr'), corrL=$('#vi-corr-lbl'), step=$('#vi-step'), reset=$('#vi-reset');
const W=640,H=300, padL=70, padR=20, padT=24, padB=46;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
// target: zero-mean bivariate Gaussian, unit variances, correlation ρ.
// log p(x) ≡ 0 reference (we measure ELBO relative to the constant evidence; report ELBO and KL).
// For a unit-variance correlated Gaussian, the optimal mean-field q has variances (1-ρ²) each.
// Track CAVI's q-variance v (shared by symmetry) starting at 1 (prior), converging to 1-ρ².
let history=[]; // {iter, elbo, kl}
let v=1.0;
const maxIter=14;
function klAndElbo(vq){
  const rho=+corr.value;
  // KL(q ‖ p) for zero-mean Gaussians with Σ_q=diag(vq,vq), Σ_p=[[1,ρ],[ρ,1]]
  const detP=1-rho*rho;
  // Σ_p^{-1} = 1/detP [[1,-ρ],[-ρ,1]]
  const trace=(1/detP)*(vq+vq); // tr(Σp^{-1} Σq) = (1/detP)(1·vq + 1·vq)
  const k=2;
  const logdet=Math.log(detP) - 2*Math.log(vq); // ln(detΣp/detΣq), detΣq = vq²
  const kl=0.5*(trace - k + logdet);
  // evidence log p(x): use a fixed reference value so ELBO = ref - kl is displayable
  const logpx=0; // reference
  return {kl:Math.max(kl,0), elbo:logpx-Math.max(kl,0)};
}
function reseed(){ v=1.0; history=[]; const r=klAndElbo(v); history.push({iter:0,elbo:r.elbo,kl:r.kl}); }
function doStep(){
  if(history.length-1>=maxIter) return;
  const rho=+corr.value; const target=1-rho*rho;
  v = v + 0.55*(target - v); // damped move toward CAVI fixed point (monotone)
  const r=klAndElbo(v); history.push({iter:history.length, elbo:r.elbo, kl:r.kl});
}
function render(){
  svg.innerHTML='';
  corrL.textContent='ρ = '+(+corr.value).toFixed(2);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  const klMax=Math.max(0.5, ...history.map(h=>h.kl), 1e-6);
  const lo=-klMax*1.05, hi=klMax*0.15; // ELBO is negative (=-kl), KL positive
  const SX=i=>x0+(i/maxIter)*(x1-x0);
  const SY=val=>y0+(val-lo)/((hi-lo)||1)*(y1-y0);
  // zero line (log p(x) reference)
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--mute)','stroke-dasharray':'5 4'}));
  const zt=SVG('text',{x:x1-6,y:SY(0)-6,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); zt.textContent='log p(x) (evidence)'; svg.appendChild(zt);
  // ELBO curve (rising toward 0)
  let de='M', dk='M';
  history.forEach((h,i)=>{ de+=' '+SX(h.iter).toFixed(1)+' '+SY(h.elbo).toFixed(1); dk+=' '+SX(h.iter).toFixed(1)+' '+SY(h.kl).toFixed(1); });
  svg.appendChild(SVG('path',{d:de,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  svg.appendChild(SVG('path',{d:dk,fill:'none',stroke:'var(--pink)','stroke-width':2.4}));
  history.forEach(h=>{ svg.appendChild(SVG('circle',{cx:SX(h.iter),cy:SY(h.elbo),r:3,fill:'var(--yellow)'})); svg.appendChild(SVG('circle',{cx:SX(h.iter),cy:SY(h.kl),r:3,fill:'var(--pink)'})); });
  function leg(x,y,c,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+20,y2:y,stroke:c,'stroke-width':2.4})); const tt=SVG('text',{x:x+26,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+10,'var(--yellow)','ELBO(q)'); leg(x0+10,y1+28,'var(--pink)','KL(q ‖ p)');
  const cap=SVG('text',{x:(x0+x1)/2,y:H-10,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='CAVI iteration'; svg.appendChild(cap);
  const last=history[history.length-1]; const rho=+corr.value; const resid=klAndElbo(1-rho*rho).kl;
  out.textContent =
    'log p(x) = ELBO(q) + KL(q ‖ p(·|x)),  KL ≥ 0  ⇒  ELBO ≤ log p(x)\n'+
    'iteration '+last.iter+' of '+maxIter+':   ELBO = '+last.elbo.toFixed(4)+'   (relative to evidence reference 0)\n'+
    'KL(q ‖ p) = '+last.kl.toFixed(4)+'   — every CAVI step raises the ELBO and lowers this gap\n'+
    (rho>0.001 ? ('mean-field cannot capture correlation ρ='+rho.toFixed(2)+': KL bottoms out at '+resid.toFixed(4)+' > 0 (the cost of factorizing)')
               : 'ρ = 0: target already factorizes, so CAVI drives KL all the way to 0 (ELBO meets log p(x))');
}
corr.addEventListener('input',()=>{ reseed(); render(); });
step.addEventListener('click',()=>{ doStep(); render(); });
reset.addEventListener('click',()=>{ reseed(); render(); });
reseed(); render();

const svg=$('#gibbs-svg'), out=$('#gibbs-out'), Tsl=$('#gibbs-T'), TL=$('#gibbs-T-lbl'), step=$('#gibbs-step'), reset=$('#gibbs-reset');
const W=640,H=320, N=6, J=1;
let seed=98765; function rnd(){ seed=(seed*1664525+1013904223)>>>0; return seed/4294967296; }
let spin=[], samples=[], sweeps=0;
const BINS=11; // magnetization buckets from -1..1
function initGrid(){ seed=98765; spin=[]; for(let i=0;i<N;i++){ spin.push([]); for(let j=0;j<N;j++) spin[i].push(rnd()<0.5?-1:1); } samples=new Array(BINS).fill(0); sweeps=0; }
function neigh(i,j){ const ns=[]; if(i>0)ns.push([i-1,j]); if(i<N-1)ns.push([i+1,j]); if(j>0)ns.push([i,j-1]); if(j<N-1)ns.push([i,j+1]); return ns; }
function magnet(){ let m=0; for(let i=0;i<N;i++) for(let j=0;j<N;j++) m+=spin[i][j]; return m/(N*N); }
function gibbsSweep(){ const T=+Tsl.value; for(let i=0;i<N;i++) for(let j=0;j<N;j++){ let s=0; for(const [a,b] of neigh(i,j)) s+=spin[a][b]; const pPlus=1/(1+Math.exp(-2*J*s/T)); spin[i][j]= rnd()<pPlus?1:-1; } }
function record(){ const m=magnet(); let b=Math.round((m+1)/2*(BINS-1)); b=Math.max(0,Math.min(BINS-1,b)); samples[b]++; }
function run(k){ for(let t=0;t<k;t++){ gibbsSweep(); record(); sweeps++; } }
function render(){
  svg.innerHTML='';
  TL.textContent='T = '+(+Tsl.value).toFixed(1);
  // left: grid
  const gx=24, gy=40, cell=34;
  for(let i=0;i<N;i++) for(let j=0;j<N;j++){ const up=spin[i][j]===1; svg.appendChild(SVG('rect',{x:gx+j*cell,y:gy+i*cell,width:cell-3,height:cell-3,rx:4,fill:up?'var(--cyan)':'var(--violet)',opacity:0.85})); }
  const gl=SVG('text',{x:gx,y:gy-12,'font-size':12,fill:'var(--mute)'}); gl.textContent='current state (cyan +1 / violet −1)'; svg.appendChild(gl);
  // right: histogram of magnetization
  const hx0=300, hx1=W-24, hy0=H-50, hy1=50;
  svg.appendChild(SVG('line',{x1:hx0,y1:hy0,x2:hx1,y2:hy0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:hx0,y1:hy0,x2:hx0,y2:hy1,stroke:'var(--line)'}));
  const total=samples.reduce((a,b)=>a+b,0)||1;
  const maxFrac=Math.max(0.1, ...samples.map(c=>c/total));
  const bw=(hx1-hx0)/BINS;
  for(let b=0;b<BINS;b++){ const frac=samples[b]/total; const h=(frac/maxFrac)*(hy0-hy1); svg.appendChild(SVG('rect',{x:hx0+b*bw+2,y:hy0-h,width:bw-4,height:h,rx:2,fill:'var(--yellow)',opacity:0.9})); }
  const hl=SVG('text',{x:(hx0+hx1)/2,y:hy1-16,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); hl.textContent='empirical P(magnetization)'; svg.appendChild(hl);
  const ax=SVG('text',{x:(hx0+hx1)/2,y:H-18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); ax.textContent='magnetization  −1 ……… 0 ……… +1'; svg.appendChild(ax);
  out.textContent =
    'Gibbs: resample each spin x_i ~ p(x_i | blanket) = σ(2J·Σ_neighbors / T)  — Z cancels, blanket only\n'+
    'sweeps so far: '+sweeps+',   current magnetization = '+magnet().toFixed(3)+'\n'+
    'the chain leaves the Ising distribution invariant ⇒ stationary = target; the histogram is the empirical P(magnetization)\n'+
    (sweeps<60 ? 'still warming up — run more sweeps to let the chain mix' : (+Tsl.value<1.6 ? 'low T: target concentrates on aligned states (peaks near ±1) — slow mixing' : 'high T: target spreads around 0 — fast mixing'));
}
Tsl.addEventListener('input',render);
step.addEventListener('click',()=>{ run(50); render(); });
reset.addEventListener('click',()=>{ initGrid(); render(); });
initGrid(); render();
